{
  "implementation": "def solve(case):
    threshold = case["threshold"]
    calls = case["calls"]
    accepted = []
    diagnostics = []
    for call in calls:
        call_id = call["call_id"]
        loss_without = call["loss_without_call"]
        loss_with = call["loss_with_call"]
        tokens = call["prediction_tokens"]
        parseable = call["parseable"]
        gain = loss_without - loss_with
        if tokens <= 0:
            norm_gain = 0.0
        else:
            norm_gain = gain / tokens
        norm_gain = round(norm_gain, 8)
        accepted_flag = parseable and norm_gain >= threshold
        if accepted_flag:
            accepted.append(call_id)
        diagnostics.append({
            "accepted": accepted_flag,
            "call_id": call_id,
            "normalized_gain": norm_gain
        })
    return {
        "accepted_call_ids": accepted,
        "diagnostics": diagnostics
    }"
}
